var img = document.getElementById('lazy');
var io = new IntersectionObserver(function (entries) {
  if (entries[0].isIntersecting) {
    img.src = img.dataset.src;
    document.getElementById('msg').textContent = 'Image loaded because it entered the viewport!';
    io.disconnect();
  }
});
io.observe(img);

var store;
try { localStorage.setItem('__t', '1'); localStorage.removeItem('__t'); store = localStorage; document.getElementById('note').textContent = 'Using real localStorage.'; }
catch (e) { var mem = {}; store = { getItem: function (k) { return k in mem ? mem[k] : null; }, setItem: function (k, v) { mem[k] = String(v); }, removeItem: function (k) { delete mem[k]; } };
  document.getElementById('note').textContent = 'Storage blocked in this sandbox - using an in-memory fallback.'; }
var el = document.getElementById('count');
el.textContent = store.getItem('visits') || '0';
document.getElementById('inc').onclick = function () { var n = Number(store.getItem('visits') || 0) + 1; store.setItem('visits', n); el.textContent = n; };
document.getElementById('reset').onclick = function () { store.removeItem('visits'); el.textContent = '0'; };

document.getElementById('go').addEventListener('click', function () {
  var out = document.getElementById('out');
  if (!('geolocation' in navigator)) { out.textContent = 'Geolocation not supported.'; return; }
  out.textContent = 'Asking for permission...';
  navigator.geolocation.getCurrentPosition(function (p) {
    out.textContent = 'Latitude: ' + p.coords.latitude.toFixed(4) + '\nLongitude: ' + p.coords.longitude.toFixed(4) + '\nAccuracy: ' + Math.round(p.coords.accuracy) + ' m';
  }, function (e) {
    out.textContent = 'Could not get location (code ' + e.code + '): ' + e.message + '\nThis is normal in sandboxed previews - handle it gracefully!';
  }, { timeout: 8000 });
});

document.querySelectorAll('.card').forEach(function (c) {
  c.addEventListener('dragstart', function (e) { e.dataTransfer.setData('text/plain', c.id); });
});
document.querySelectorAll('.col').forEach(function (col) {
  col.addEventListener('dragover', function (e) { e.preventDefault(); col.classList.add('over'); });
  col.addEventListener('dragleave', function () { col.classList.remove('over'); });
  col.addEventListener('drop', function (e) {
    e.preventDefault(); col.classList.remove('over');
    var card = document.getElementById(e.dataTransfer.getData('text/plain'));
    if (card) col.appendChild(card);
  });
});

topics.description:
JavaScript in a page runs on a **single main thread** shared with rendering and user input. A long calculation freezes the page. A **Web Worker** runs a script in a **background thread**.

### Key facts
- Workers have **no access to the DOM**, `window` or `document`.
- They talk to the page only by **messages** (`postMessage` / `onmessage`). Data is *copied* (structured clone) or transferred.
- They can use `fetch`, timers, IndexedDB, `importScripts()` and modules.

### Basic usage
```js
// main.js
const worker = new Worker('worker.js');
worker.postMessage({ n: 40 });
worker.onmessage = (e) => console.log('result', e.data);
worker.onerror = (e) => console.error(e.message);
// worker.terminate();  // stop it

// worker.js
self.onmessage = (e) => {
  const result = heavyWork(e.data.n);
  self.postMessage(result);
};
```

### Worker types
| Type | Use |
|---|---|
| Dedicated Worker | One page owns it |
| Shared Worker | Shared by several tabs |
| Service Worker | Offline cache, push, network proxy (PWA) |

### When to use
Image processing, parsing big files, encryption, sorting huge data, data crunching. **Not** for small tasks - creating a worker has overhead.

### Inline workers
Create from a Blob URL when you do not want a separate file (see the example).

